<template>
    <component :is="mobile ? 'div' : IntegrationLayout" class="workshop" :class="{'transfer-mobile':mobile}" tool-id="peer-transfer" title="手机与电脑双向互传" subtitle="在同一局域网的浏览器之间传文件或文字，文件不存到服务器。">
        <h1 v-if="mobile" class="view-title">工具箱双向互传</h1>
        <div class="workshop-grid"><section class="workshop-panel"><h2>连接另一端</h2><template v-if="!mobile"><label>手机扫码访问地址<select v-model="address" :disabled="!!room"><option v-for="item in addresses" :key="item" :value="item">{{ item }}</option></select></label><p class="workshop-note">手机与电脑需在同一网段，工具箱需使用 Lan 模式。房间30分钟有效，仅允许另一端加入一次。</p><button id="transfer-create" class="btn btn-primary" :disabled="!!room || busy" @click="createRoom">创建互传房间</button><img v-if="qr" class="transfer-qr" :src="qr" alt="另一端扫码加入互传房间"/><button v-if="inviteUrl" class="btn" @click="copyInvite">复制邀请链接</button></template><button v-else-if="!room" id="transfer-join" class="btn btn-primary" :disabled="busy || !invitation" @click="joinRoom">加入互传房间</button><p role="status" class="workshop-note">{{ status }}</p><p v-if="room" class="workshop-small">有效期至 {{ new Date(room.expiresAt).toLocaleTimeString() }}</p><button v-if="room" class="btn" @click="closeRoom">停止并关闭连接</button><p v-if="error" class="workshop-error" role="alert">{{ error }}</p><p class="workshop-note">浏览器直接传输，不使用外部中转。网络隔离或防火墙可能阻止连接；失败时可使用已有的手机相册上传。每文件最多100MiB，已接收文件合计最多200MiB，需手动下载保存。</p></section>
        <section class="workshop-panel"><h2>文件与文字</h2><label>发送文件<input id="transfer-file" type="file" :disabled="!connected || !!outgoing" @change="offerFile($event.target.files?.[0]); $event.target.value=''"/></label><div v-if="outgoing" class="workshop-item"><strong>{{ outgoing.file.name }}</strong><p class="workshop-note">{{ outgoing.status }}</p><progress :value="outgoing.progress" max="100" aria-label="文件发送进度"/><button class="btn btn-sm" @click="cancelOutgoing">取消发送</button></div><div v-if="incoming" class="workshop-item"><strong>对方发送：{{ incoming.name }}</strong><p class="workshop-note">{{ formatSize(incoming.size) }} · {{ incoming.accepted ? `接收 ${incoming.progress}%` : '等待你确认' }}</p><div class="ext-row"><button v-if="!incoming.accepted" id="transfer-accept" class="btn btn-primary" @click="acceptFile">接收</button><button class="btn" @click="rejectFile">{{ incoming.accepted ? '停止接收' : '拒绝' }}</button></div></div><ul class="workshop-list"><li v-for="item in received" :key="item.id" class="workshop-item"><strong>{{ item.name }}</strong><p class="workshop-small">{{ formatSize(item.size) }} · SHA-256 核对通过</p><div class="ext-row"><a class="btn btn-sm" :href="item.url" :download="item.name">下载保存</a><button class="btn btn-sm" @click="removeReceived(item)">移除</button></div></li></ul><label>发送文字<textarea id="transfer-text" v-model="text" maxlength="16384" placeholder="输入要发送的文字"/></label><button id="transfer-send-text" class="btn btn-primary" :disabled="!connected || !text.trim()" @click="sendText">发送文字</button><ul class="workshop-list"><li v-for="(message,index) in messages" :key="index" class="workshop-item"><span class="workshop-small">{{ message.self ? '我发送的' : '对方发来的' }}</span><pre class="workshop-result">{{ message.text }}</pre><button class="btn btn-sm" @click="copy(message.text)">复制</button></li></ul></section></div>
    </component>
</template>
<script setup>
import { ref, computed, onMounted, onBeforeUnmount } from 'vue';
import { useRoute } from 'vue-router';
import { sha256 } from '@noble/hashes/sha256';
import QRCode from 'qrcode';
import IntegrationLayout from '../components/IntegrationLayout.vue';
import { copyText } from '../utils/clipboard.js';
import { formatSize } from '../utils/tool-files.js';
import { TRANSFER_LIMITS, safeFileName, validOffer, digestHex, sendPeerFile } from '../utils/peer-transfer.js';
const route=useRoute(),mobile=computed(()=>!!route.meta.mobileUpload),addresses=ref([location.origin]),address=ref(location.origin),room=ref(null),busy=ref(false),connected=ref(false),status=ref('尚未连接'),error=ref(''),qr=ref(''),inviteUrl=ref(''),text=ref(''),messages=ref([]),received=ref([]),incoming=ref(null),outgoing=ref(null);
const fragment=new URLSearchParams(location.hash.slice(1)),invitation=fragment.has('room')&&fragment.has('invite')?{id:fragment.get('room'),invite:fragment.get('invite')}:null;
let peer,channel,timer,controller,polling=false,sequence=0,side='',ice=[],stopped=false,sendController,receiveParts=[],receiveHash,receiveBytes=0,sendChain=Promise.resolve(),signalChain=Promise.resolve(),offered=false;
async function request(path,{method='GET',body,signal=controller?.signal,ticket=room.value?.ticket}={}){const response=await fetch('/api/transfer'+path,{method,headers:{'X-Toolbox-Transfer':'1',...(ticket?{'X-Toolbox-Transfer-Token':ticket}:{}),...(method!=='GET'?{'Content-Type':'application/json'}:{})},body:method==='GET'?undefined:JSON.stringify(body||{}),signal:signal?AbortSignal.any([signal,AbortSignal.timeout(12000)]):AbortSignal.timeout(12000)});const result=await response.json();if(!response.ok)throw new Error(result.message||'互传连接失败');return result;}
function signal(kind,payload){signalChain=signalChain.then(()=>request(`/rooms/${room.value.id}/signal`,{method:'POST',body:{kind,payload}}));signalChain.catch(e=>{if(!stopped){error.value=e.message;status.value='连接失败，请重新创建房间';}});return signalChain;}
function attachChannel(value){channel=value;channel.binaryType='arraybuffer';channel.onopen=()=>{connected.value=true;status.value='两端已连接，可以双向发送';};channel.onclose=()=>{connected.value=false;status.value='对方已断开，请重新创建房间';cancelOutgoing();resetIncoming();};channel.onerror=()=>{error.value='直传通道失败，请重建连接';};channel.onmessage=event=>{sendChain=sendChain.then(()=>onMessage(event.data)).catch(e=>{error.value=e.message;resetIncoming();});};}
function createPeer(){if(!globalThis.RTCPeerConnection)throw new Error('当前浏览器不支持 WebRTC，请使用新版 Chrome、Edge 或 Safari');peer=new RTCPeerConnection({iceServers:[]});peer.onicecandidate=event=>{if(event.candidate&&!stopped)void signal('ice',event.candidate.toJSON());};peer.ondatachannel=event=>attachChannel(event.channel);peer.onconnectionstatechange=()=>{if(['failed','disconnected'].includes(peer.connectionState)){connected.value=false;status.value='网络连接中断，请重建房间';}};if(side==='owner')attachChannel(peer.createDataChannel('toolbox-files',{ordered:true}));}
async function negotiate(event){if(event.kind==='joined'&&side==='owner'&&!offered){offered=true;await peer.setLocalDescription(await peer.createOffer());await signal('offer',peer.localDescription.toJSON());}else if(event.kind==='offer'&&side==='guest'){await peer.setRemoteDescription(event.payload);await flushIce();await peer.setLocalDescription(await peer.createAnswer());await signal('answer',peer.localDescription.toJSON());}else if(event.kind==='answer'&&side==='owner'){await peer.setRemoteDescription(event.payload);await flushIce();}else if(event.kind==='ice'){if(peer.remoteDescription)await peer.addIceCandidate(event.payload);else if(ice.length<128)ice.push(event.payload);}else if(event.kind==='left'){status.value='对方已离开，请重新创建房间';connected.value=false;peer.close();}}
async function flushIce(){for(const candidate of ice)await peer.addIceCandidate(candidate);ice=[];}
async function poll(){if(stopped||!room.value||polling)return;polling=true;try{const result=await request(`/rooms/${room.value.id}?after=${sequence}`);for(const event of result.events){if(stopped)return;await negotiate(event);}sequence=result.sequence;}catch(e){if(!stopped){error.value=e.message;await closeRoom();status.value='房间已失效，请重新连接';}}finally{polling=false;if(!stopped&&room.value)timer=setTimeout(poll,connected.value?1500:500);}}
async function createRoom(){busy.value=true;error.value='';stopped=false;controller=new AbortController();try{room.value=await request('/rooms',{method:'POST'});side='owner';sequence=0;offered=false;signalChain=Promise.resolve();createPeer();inviteUrl.value=`${address.value}/transfer#room=${room.value.id}&invite=${room.value.invite}`;const style=getComputedStyle(document.documentElement);qr.value=await QRCode.toDataURL(inviteUrl.value,{width:280,margin:3,color:{dark:style.getPropertyValue('--adb-qr-foreground').trim(),light:style.getPropertyValue('--adb-qr-background').trim()}});status.value='等待另一端扫码加入…';void poll();}catch(e){error.value=e.message;await closeRoom();}finally{busy.value=false;}}
async function joinRoom(){busy.value=true;error.value='';stopped=false;controller=new AbortController();try{room.value=await request(`/rooms/${encodeURIComponent(invitation.id)}/join`,{method:'POST',body:{invite:invitation.invite}});history.replaceState(null,'',location.pathname);side='guest';sequence=0;signalChain=Promise.resolve();createPeer();status.value='正在建立直传连接…';void poll();}catch(e){error.value=e.message;}finally{busy.value=false;}}
function send(data){if(!channel||channel.readyState!=='open')throw new Error('两端尚未连接');channel.send(JSON.stringify(data));}
function randomId(){return Array.from(crypto.getRandomValues(new Uint8Array(12)),v=>v.toString(16).padStart(2,'0')).join('');}
function offerFile(file){error.value='';if(!file)return;if(!file.size||file.size>TRANSFER_LIMITS.file){error.value='每个文件需为1字节～100MiB';return;}try{const id=randomId();outgoing.value={id,file,status:'等待对方确认接收',progress:0};send({type:'file',id,name:safeFileName(file.name),size:file.size});}catch(e){error.value=e.message;outgoing.value=null;}}
function acceptFile(){if(!incoming.value)return;if(received.value.reduce((sum,item)=>sum+item.size,0)+incoming.value.size>TRANSFER_LIMITS.total){error.value='接收结果达到200MiB，请先下载并移除已有文件';return;}receiveParts=[];receiveBytes=0;receiveHash=sha256.create();incoming.value.accepted=true;send({type:'accept',id:incoming.value.id});}
function resetIncoming(){incoming.value=null;receiveParts=[];receiveHash?.destroy();receiveHash=null;receiveBytes=0;}
function rejectFile(){if(incoming.value){try{send({type:'reject',id:incoming.value.id});}catch{ /* 连接关闭时仍清理本端 */ }}resetIncoming();}
function cancelOutgoing(){sendController?.abort();if(outgoing.value){try{send({type:'cancel',id:outgoing.value.id});}catch{ /* 连接关闭 */ }}outgoing.value=null;}
async function onMessage(data){
    if(typeof data!=='string'){
        if(!(data instanceof ArrayBuffer)||!incoming.value?.accepted) return;
        if(data.byteLength>64*1024||receiveBytes+data.byteLength>incoming.value.size){rejectFile();throw new Error('收到的分块超过限制，已停止接收');}
        receiveBytes+=data.byteLength;receiveParts.push(data);receiveHash.update(new Uint8Array(data));incoming.value.progress=Math.round(receiveBytes/incoming.value.size*100);return;
    }
    if(data.length>24*1024)throw new Error('收到的控制消息过长');let message;try{message=JSON.parse(data);}catch{throw new Error('收到无效传输消息');}
    if(message.type==='text'&&typeof message.text==='string'&&message.text.length<=TRANSFER_LIMITS.text){messages.value.unshift({self:false,text:message.text});messages.value=messages.value.slice(0,30);}
    else if(message.type==='file'){if(!validOffer(message))throw new Error('收到无效文件请求');if(incoming.value){send({type:'reject',id:message.id});return;}incoming.value={...message,name:safeFileName(message.name),accepted:false,progress:0};}
    else if(message.type==='accept'&&outgoing.value?.id===message.id){
        if(sendController&&!sendController.signal.aborted)return;
        const entry=outgoing.value;sendController=new AbortController();entry.status='正在发送';
        // 不等待发送循环，否则双向同时发送时接收消息会被阻塞。
        void sendPeerFile(channel,entry.file,entry.id,{signal:sendController.signal,onProgress:value=>{entry.progress=value;entry.status=`发送 ${value}%`;}}).then(()=>{if(outgoing.value?.id===entry.id)outgoing.value.status='已发送，等待对方校验';}).catch(e=>{if(outgoing.value?.id===entry.id){error.value=e.message;cancelOutgoing();}});
    }else if(message.type==='end'&&incoming.value?.id===message.id&&incoming.value.accepted){
        if(receiveBytes!==incoming.value.size||!/^[a-f0-9]{64}$/.test(message.hash)||digestHex(receiveHash.digest())!==message.hash){rejectFile();throw new Error('文件大小或 SHA-256 校验失败，请重新发送');}
        const blob=new Blob(receiveParts,{type:'application/octet-stream'});received.value.push({id:incoming.value.id,name:incoming.value.name,size:blob.size,url:URL.createObjectURL(blob)});send({type:'received',id:incoming.value.id});resetIncoming();status.value='文件已接收并核对，请点击下载保存';
    }else if(message.type==='received'&&outgoing.value?.id===message.id){status.value=`对方已完整接收 ${outgoing.value.file.name}`;sendController=null;outgoing.value=null;}
    else if(['reject','cancel'].includes(message.type)){if(outgoing.value?.id===message.id){sendController?.abort();sendController=null;outgoing.value=null;status.value='对方拒绝或停止接收';}if(incoming.value?.id===message.id)resetIncoming();}
}
function removeReceived(item){URL.revokeObjectURL(item.url);received.value=received.value.filter(other=>other.id!==item.id);}
function sendText(){try{send({type:'text',text:text.value});messages.value.unshift({self:true,text:text.value});messages.value=messages.value.slice(0,30);text.value='';}catch(e){error.value=e.message;}}
async function copy(value){try{await copyText(value);}catch{error.value='复制失败，请手动复制';}}
const copyInvite=()=>copy(inviteUrl.value);
async function closeRoom(){stopped=true;clearTimeout(timer);controller?.abort();cancelOutgoing();resetIncoming();channel?.close();peer?.close();channel=null;peer=null;ice=[];connected.value=false;const previous=room.value;room.value=null;qr.value='';inviteUrl.value='';if(previous)try{await request(`/rooms/${previous.id}`,{method:'DELETE',signal:AbortSignal.timeout(3000),ticket:previous.ticket});}catch{ /* 短期房间会自动到期 */ }status.value='连接已关闭';}
const unload=()=>{void closeRoom();};
onMounted(async()=>{window.addEventListener('pagehide',unload);if(mobile.value){if(!invitation)error.value='邀请链接不完整，请从电脑重新扫码';return;}try{const config=await request('/config');if(config.addresses.length){addresses.value=[...new Set([location.origin,...config.addresses])];address.value=config.addresses[0];}}catch(e){error.value=e.message;}});
onBeforeUnmount(()=>{void closeRoom();for(const item of received.value)URL.revokeObjectURL(item.url);window.removeEventListener('pagehide',unload);});
</script>
